import{_ as a,o as r,c as o,a2 as d}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"10.2 常用光源与灯具","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/10-2-chang-yong-guang-yuan-yu-deng-ju.md","filePath":"electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/10-2-chang-yong-guang-yuan-yu-deng-ju.md","lastUpdated":1793096070000}'),l={name:"electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/10-2-chang-yong-guang-yuan-yu-deng-ju.md"};function e(n,t,i,s,h,g){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="_10-2-常用光源与灯具" tabindex="-1">10.2 常用光源与灯具 <a class="header-anchor" href="#_10-2-常用光源与灯具" aria-label="Permalink to &quot;10.2 常用光源与灯具&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>从&quot;灯泡里的钨丝&quot;到&quot;半导体 LED&quot;,光源经历了多次换代。这一节认识常用光源的特点、优缺点和适用场合,重点是<strong>荧光灯</strong>的启动原理和 <strong>LED</strong> 灯的优势。</p><h2 id="一、白炽灯-已逐步淘汰" tabindex="-1">一、白炽灯(已逐步淘汰) <a class="header-anchor" href="#一、白炽灯-已逐步淘汰" aria-label="Permalink to &quot;一、白炽灯(已逐步淘汰)&quot;">​</a></h2><ul><li>靠钨丝<strong>发热到白炽</strong>发光,结构简单、价格便宜、显色性好、可调光;</li><li>缺点:<strong>发光效率低</strong>(大部分电能变成热)、寿命短,现在基本退出市场。</li></ul><h2 id="二、荧光灯-日光灯" tabindex="-1">二、荧光灯(日光灯) <a class="header-anchor" href="#二、荧光灯-日光灯" aria-label="Permalink to &quot;二、荧光灯(日光灯)&quot;">​</a></h2><p>靠<strong>气体放电</strong>激发荧光粉发光:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>灯丝预热 ──► 启动器断开 ──► 镇流器产生高压 ──► 灯管放电点亮</span></span></code></pre></div><p>主要部件:</p><table tabindex="0"><thead><tr><th>部件</th><th>作用</th></tr></thead><tbody><tr><td><strong>灯管</strong></td><td>内部充惰性气体+汞,放电时激发荧光粉发光</td></tr><tr><td><strong>镇流器</strong></td><td>启动时产生高压点燃灯管,运行时<strong>限流</strong>(限制电流)</td></tr><tr><td><strong>启辉器(启动器)</strong></td><td>启动时先接通预热灯丝,再突然断开,配合镇流器产生高压</td></tr></tbody></table><blockquote><p>💡 通俗理解:<strong>镇流器是&quot;点火器+限流器&quot;,启辉器是&quot;开关的帮手&quot;</strong>。灯管点亮后,启辉器就不起作用了。 ⚠️ 判断题高频:镇流器在灯管启动时产生高压,正常运行时<strong>限制电流</strong>,两者都靠它。</p></blockquote><h2 id="三、节能灯-紧凑型荧光灯" tabindex="-1">三、节能灯(紧凑型荧光灯) <a class="header-anchor" href="#三、节能灯-紧凑型荧光灯" aria-label="Permalink to &quot;三、节能灯(紧凑型荧光灯)&quot;">​</a></h2><ul><li>把荧光灯管<strong>弯曲缩小</strong>,配上电子镇流器;</li><li>比白炽灯<strong>省电约 70%~80%</strong>,寿命长;</li><li>属荧光灯家族,内含少量汞,<strong>不能乱扔</strong>,要回收。</li></ul><h2 id="四、led-灯-半导体发光" tabindex="-1">四、LED 灯(半导体发光) <a class="header-anchor" href="#四、led-灯-半导体发光" aria-label="Permalink to &quot;四、LED 灯(半导体发光)&quot;">​</a></h2><ul><li>靠<strong>半导体芯片(PN 结)通电发光</strong>,是现在的主流;</li><li><strong>发光效率最高、寿命最长、体积小、可调色温</strong>,几乎无频闪;</li><li>需配套<strong>驱动器(恒流电源)</strong>;</li><li>省电:同样亮度只有白炽灯的几分之一。</li></ul><h2 id="五、高压气体放电灯-户外、厂房" tabindex="-1">五、高压气体放电灯(户外、厂房) <a class="header-anchor" href="#五、高压气体放电灯-户外、厂房" aria-label="Permalink to &quot;五、高压气体放电灯(户外、厂房)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>光源</th><th>特点</th><th>适用</th></tr></thead><tbody><tr><td><strong>高压汞灯</strong></td><td>效率较高,启动慢(需数分钟),光色偏青白</td><td>广场、厂房、路灯</td></tr><tr><td><strong>高压钠灯</strong></td><td>效率很高,光色偏黄(显色差),寿命长</td><td>公路、道路、隧道</td></tr><tr><td><strong>金属卤化物灯</strong></td><td>光色好、效率高</td><td>体育场、厂房、商照</td></tr></tbody></table><blockquote><p>⚠️ 判断题常考:高压汞灯、高压钠灯启动慢(通电后要几分钟才全亮),且<strong>熄灭后不能立即再启动</strong>。</p></blockquote><h2 id="六、常用光源对比速查" tabindex="-1">六、常用光源对比速查 <a class="header-anchor" href="#六、常用光源对比速查" aria-label="Permalink to &quot;六、常用光源对比速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>光源</th><th>效率</th><th>寿命</th><th>显色性</th><th>特点</th></tr></thead><tbody><tr><td>白炽灯</td><td>低</td><td>短</td><td>好</td><td>即将淘汰</td></tr><tr><td>荧光灯</td><td>较高</td><td>中</td><td>较好</td><td>需镇流器+启辉器</td></tr><tr><td>节能灯</td><td>高</td><td>较长</td><td>较好</td><td>紧凑荧光灯</td></tr><tr><td>LED</td><td>最高</td><td>最长</td><td>好</td><td>主流,需驱动器</td></tr><tr><td>高压钠灯</td><td>高</td><td>长</td><td>差(偏黄)</td><td>道路照明</td></tr></tbody></table><h2 id="七、考点提示" tabindex="-1">七、考点提示 <a class="header-anchor" href="#七、考点提示" aria-label="Permalink to &quot;七、考点提示&quot;">​</a></h2><ul><li>✅ 荧光灯三大件:灯管、<strong>镇流器</strong>(启动高压+运行限流)、启辉器。</li><li>✅ <strong>LED</strong> 效率最高、寿命最长,是当前主流。</li><li>✅ 高压汞灯/钠灯启动慢,熄灭后不能立即再启动。</li><li>⚠️ 易混点:镇流器(荧光灯必须)与驱动器(LED 必须)是两个不同的配套件,别混。</li></ul><h2 id="八、本节小结" tabindex="-1">八、本节小结 <a class="header-anchor" href="#八、本节小结" aria-label="Permalink to &quot;八、本节小结&quot;">​</a></h2><ul><li>白炽灯→荧光灯→节能灯→LED,效率越来越高。</li><li>荧光灯靠镇流器启动限流、启辉器配合启动。</li><li>高压气体放电灯用于户外大空间,但启动慢。</li></ul><h2 id="九、自测练习" tabindex="-1">九、自测练习 <a class="header-anchor" href="#九、自测练习" aria-label="Permalink to &quot;九、自测练习&quot;">​</a></h2><ol><li>(单选)荧光灯启动时产生高压点燃灯管,运行时限制电流的元件是()。 A. 启辉器　B. 镇流器　C. 灯丝　D. 电容器</li><li>(单选)发光效率最高、寿命最长,目前应用最广的光源是()。 A. 白炽灯　B. 高压汞灯　C. LED 灯　D. 卤钨灯</li><li>(判断)高压汞灯通电后很快就能达到最亮。( )</li><li>(单选)道路、隧道照明常用光效高、寿命长但显色性较差的光源是()。 A. 高压钠灯　B. 白炽灯　C. 节能灯　D. LED</li><li>(判断)节能灯属于荧光灯家族,含有微量汞,应回收处理。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。镇流器启动产生高压、运行限流。</li><li><strong>C</strong>。LED 效率最高、寿命最长。</li><li><strong>×</strong>。高压汞灯启动慢,需数分钟才全亮。</li><li><strong>A</strong>。高压钠灯光效高、寿命长、光色偏黄,适合道路照明。</li><li><strong>√</strong>。节能灯含汞,不能随意丢弃。</li></ol></details>',27)])])}const b=a(l,[["render",e]]);export{c as __pageData,b as default};
